import data from "./data/timeline.json";

// timeline.json is generated by scripts/build_timeline.py from the measured
// voice-over durations: every scene boundary and caption follows the audio.

export type SceneId =
  | "hook"
  | "title"
  | "transponder"
  | "goodnight"
  | "military"
  | "curvature"
  | "satellite"
  | "search"
  | "rule"
  | "end";

export const TIMELINE = data;

export const scene = (id: SceneId) => {
  const s = data.scenes.find((x) => x.id === id);
  if (!s) throw new Error(`Unknown scene ${id}`);
  return s;
};

/** Voice-over chunk starts/durations of a scene, in frames local to the scene. */
export const cues = (id: SceneId) => {
  const s = scene(id);
  return data.captions
    .filter((c) => c.scene === id)
    .map((c) => ({ at: c.from - s.from, dur: c.durationInFrames, end: c.from - s.from + c.durationInFrames }));
};
